+import type {EventEmitter} from 'node:events';
+
+export type Outcome = 'response' | 'error';
+
+/**
+Watch an emitter for its first `response` or `error` event.
+
+The callback is called at most once, with the event name and the first event argument. Both listeners are removed as soon as either event fires.
+
+@returns A function that removes both listeners without calling the callback.
+*/
+export default function watchOutcome(emitter: EventEmitter, callback: (event: Outcome, payload: unknown) => void): () => void {
+	const cancel = () => {
+		emitter.off('response', onResponse);
+		emitter.off('error', onError);
+	};
+
+	const onResponse = (payload: unknown) => {
+		cancel();
+		callback('response', payload);
+	};
+
+	const onError = (payload: unknown) => {
+		cancel();
+		callback('error', payload);
+	};
+
+	emitter.on('response', onResponse);
+	emitter.on('error', onError);
+
+	return cancel;
+}
+
+export {watchOutcome};
diff --git a/test/first-outcome.ts b/test/first-outcome.ts
new file mode 100644
index 0000000..6d94b30
--- /dev/null
+++ b/test/first-outcome.ts
@@ -0,0 +1,59 @@
+import {EventEmitter} from 'node:events';
+import test from 'ava';
+import watchOutcome from '../source/first-outcome.js';
+
+test('calls back once on the first response and removes both listeners', t => {
+	const emitter = new EventEmitter();
+	const calls: unknown[][] = [];
+
+	watchOutcome(emitter, (event, payload) => {
+		calls.push([event, payload]);
+	});
+
+	emitter.emit('response', 'first', 'extra');
+	emitter.emit('response', 'second');
+	emitter.on('error', () => {});
+	emitter.emit('error', new Error('later'));
+
+	t.deepEqual(calls, [['response', 'first']]);
+	t.is(emitter.listenerCount('response'), 0);
+	t.is(emitter.listenerCount('error'), 1);
+});
+
+test('calls back once on the first error and removes both listeners', t => {
+	const emitter = new EventEmitter();
+	const error = new Error('boom');
+	const calls: unknown[][] = [];
+
+	watchOutcome(emitter, (event, payload) => {
+		calls.push([event, payload]);
+	});
+
+	emitter.emit('error', error);
+	emitter.emit('response', 'ignored');
+
+	t.deepEqual(calls, [['error', error]]);
+	t.is(emitter.listenerCount('response'), 0);
+	t.is(emitter.listenerCount('error'), 0);
+});
+
+test('cancellation removes only its own listeners', t => {
+	const emitter = new EventEmitter();
+	const unrelated = () => {};
+	emitter.on('response', unrelated);
+	emitter.on('error', unrelated);
+
+	let called = false;
+	const cancel = watchOutcome(emitter, () => {
+		called = true;
+	});
+
+	cancel();
+	cancel();
+	emitter.emit('response', 'value');
+	emitter.emit('error', new Error('boom'));
+
+	t.false(called);
+	t.deepEqual(emitter.listeners('response'), [unrelated]);
+	t.deepEqual(emitter.listeners('error'), [unrelated]);
+});
